from typing import List, Sequence

def gain(eta: float, lam: float) -> float:
    return 1.0 - eta * lam

def closed_form(eta: float, lam: Sequence[float], v: Sequence[float], k: int) -> List[float]:
    return [gain(eta, l) ** k * vi for l, vi in zip(lam, v)]

def main() -> None:
    eta, lam, v = 0.1, [8.0, 0.5], [1.0, 1.0]   # mode 0 fast, mode 1 slow
    assert abs(gain(eta, lam[0])) < abs(gain(eta, lam[1]))
    for k in (0, 5, 10, 25, 50, 100):
        x = closed_form(eta, lam, v, k)
        print(f'k={k:>4}: |x_fast|/|x_slow| = {abs(x[0])/abs(x[1]):.6e}')

if __name__ == '__main__':
    main()

from typing import List, Sequence

def gain(eta: float, lam: float) -> float:
    return 1.0 - eta * lam

def rg_step(eta: float, lam: Sequence[float], v: Sequence[float]) -> List[float]:
    return [gain(eta, l) * vi for l, vi in zip(lam, v)]

def is_fixed(eta, lam, v, tol=1e-12):
    return all(abs(a - b) <= tol for a, b in zip(rg_step(eta, lam, v), v))

def in_kernel(lam, v, tol=1e-12):
    return all(abs(l * vi) <= tol for l, vi in zip(lam, v))

def main() -> None:
    eta, lam = 0.1, [0.0, 0.0, 3.0]
    for v in ([1,1,0], [1,1,1], [0,5,0], [0,0,2]):
        print(v, 'fixed=', is_fixed(eta, lam, v), 'kernel=', in_kernel(lam, v))

if __name__ == '__main__':
    main()

from typing import List, Sequence

def gain(eta: float, lam: float) -> float:
    return 1.0 - eta * lam

def closed_form(eta: float, lam: Sequence[float], v: Sequence[float], k: int) -> List[float]:
    return [gain(eta, l) ** k * vi for l, vi in zip(lam, v)]

def main() -> None:
    eta, lam, v = 0.1, [0.5, 2.0, 7.0], [1.0, 1.0, 1.0]
    g_max = max(abs(gain(eta, l)) for l in lam)
    for k in (1, 5, 10, 20, 40, 80):
        x = closed_form(eta, lam, v, k)
        loss = sum(xi * xi for xi in x)
        print(f'k={k:>3}: L_k={loss:.6e}  L_k/g_max^(2k)={loss/g_max**(2*k):.6f}')

if __name__ == '__main__':
    main()

