function RG_FLOW(eta, lambda[1..d], v[1..d], k):
    out := new array of length d
    for i in 1..d:
        g_i    := 1 - eta * lambda[i]      # per-mode gain (Definition 2.1)
        out[i] := g_i^k * v[i]             # closed form (Theorem 3.1)
    return out

function IS_IR_FIXED_POINT(eta, lambda, v, tol):
    assert eta != 0
    for i in 1..d:
        if |lambda[i] * v[i]| > tol:
            return False          # active mode is being rescaled
    return True                   # v lies in ker(NTK): an IR fixed point

